      [L('x : a = b', 'x : a = b', 'x : a = b'), L('bo‘linuvchi', 'делимое', 'the dividend'), L('x = b · a', 'x = b · a', 'x = b · a'), L('x : 2 = 9 → x = 18', 'x : 2 = 9 → x = 18', 'x : 2 = 9 → x = 18')],
      [L('a : x = b', 'a : x = b', 'a : x = b'), L('bo‘luvchi', 'делитель', 'the divisor'), L('x = a : b', 'x = a : b', 'x = a : b'), L('40 : x = 5 → x = 8', '40 : x = 5 → x = 8', '40 : x = 5 → x = 8')]
